solve:{[tokens;codes]
  norm:{[x]lower x};
  jpat:{[x]
    s:x;
    if[count s;if[first s="-";s:1_s]];
    (count s)&all s in "0123456789"
    };
  fp:{[x]
    s:x;d:0;
    if[(first s)="-";d:1;s:1_s];
    if[(count s)&((d in 0 1)&not any s in ".")&all s in "0123456789.";
      parts:"." vs s;
      (count parts)&(((count parts)=1)&count first parts)&
        ((count parts)=2)&((count first parts)|(count last parts))];
    };
  longs:();floats:();bools:();chars:();syms:();symidx:();effective:"";recast:0;total:0;i:0;
  while[i<count tokens;
    t:norm tokens i;decl:codes i;eff:"s";
    if[jpat t;v:"J"$t;
      if[abs[v]<1000000000;eff:"j";longs,:v;total+:v]];
    if[eff="s";
      if[fp t;v:"F"$tokens i;
        if[abs[v]<1000000f;eff:"f";v:(floor v*1000f)*0.001f;floats,:v;total+:v]]];
    if[eff="s";
      if[t in ("0";"1";"t";"f";"true";"false");eff:"b";
        v:$[t in ("1";"t";"true");1b;0b];bools,:v;total+:v]];
    if[eff="s";
      if[(count tokens i)=1;eff:"c";chars,:enlist "J"$first tokens i;total+:chars last]];
    if[eff="s";syms,:distinct syms,enlist tokens i;symidx,:first where syms=tokens i;total+:last symidx];
    effective,:(string eff);
    if[not eff~decl;recast+:1];i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
    (effective;longs;floats;bools;chars;syms;symidx;recast;(floor total*1000f)*0.001f)}
