solve:{[tokens;codes]
  norm:{[s] s where s in "0123456789";};
  longs:(); floats:(); bools:(); chars:(); syms:(); symIdx:(); effective:""; recast:0; i:0;
  while[i<count tokens;
    t:tokens i; pref:codes i; ok:0;
    do:5;
      c:`$codes x?("j";"f";"b";"c";"s");
      if[not ok;
        body:norm t;
        if[(c=`j)&(count body)&all body in "0123456789";
          v:"J"$body;
          if[abs[v]<1000000000;longs,:v;effective,:"j";ok:1]];
        if[(c=`f)&(count body)&all body in ".0123456789";
          v:"F"$body;
          if[abs[v]<1000000f;floats,:0.001*floor 0.5+1000f*v;effective,:"f";ok:1]];
        if[(c=`b)&((lower t) in ("0";"1";"t";"f";"true";"false"));
          v:((lower t) in ("1";"t";"true"));
          bools,:v;effective,:"b";ok:1];
        if[(c=`c)&(1=count t);chars,:enlist "I"$t;effective,:"c";ok:1]];
        if[(c=`s)&not ok;
          ix:$[t in syms;first where syms=t;syms,:t;count[syms]-1]];
          symIdx,:ix;effective,:"s";ok:1];
      if[ok&not c~`$pref;recast+:1];
    i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
    (effective;longs;floats;bools;chars;syms;symIdx;recast;
      sum longs+floats+bools+chars+symIdx)}
