solve:{[tokens;codes]
  longs:();floats:();bools:();chars:();syms:();symidx:();effective:();recast:0;i:0;
  while[i<count tokens;tok:tokens i;code:`$codes i;fx:"";
    if[not (count tok) in 1 2;fx:"j"];
