solve:{[tokens;codes]
  jx:enlist "-?[0-9]+";
  fx:enlist "-?([0-9]+(\\.[0-9]*)?|\\.[0-9]+)";
  booleans:("0";"1";"t";"f";"true";"false");

  effective:();longs:();floats:();bools:();chars:();syms:();symidx:();recast:0;

  i:0;while[i<count tokens;
    tok:tokens i;tc:codes i;ok:0;

    if[tc~"j";
      if[(tok matches first jx)&((abs "J"$tok)<1000000000);
        effective,:tc;longs,:("J"$tok);ok:1]];

    if[not ok;if[tc~"f";
      if[(tok matches first fx)&((abs "F"$tok)<1000000f);
        effective,:tc;floats,:0.001f*floor (0.5f+1000f*"F"$tok);ok:1]]];

    if[not ok;if[tc~"b";
      if[lower[tok] in booleans;
        effective,:tc;bools,:1*(lower[tok]) in ("1";"t";"true");ok:1]]];

    if[not ok;if[tc~"c";
      if[(count tok)=1;effective,:tc;chars,:code[tok];ok:1]]];

    if[not ok;if[tc~"s";effective,:tc;syms,:enlist tok;symidx,:count[syms]-1;ok:1]];

    if[not ok;
      alt:"jfbcs";j:0;
      while[j<count alt;
        at:alt j;if[at~tc;j+:1;continue];
        tok:tokens i;ok:0;

        if[at~"j";
          if[(tok matches first jx)&((abs "J"$tok)<1000000000);
            effective,:at;longs,:("J"$tok);ok:1]];

        if[not ok;if[at~"f";
          if[(tok matches first fx)&((abs "F"$tok)<1000000f);
            effective,:at;floats,:0.001f*floor (0.5f+1000f*"F"$tok);ok:1]]];

        if[not ok;if[at~"b";
          if[lower[tok] in booleans;
            effective,:at;bools,:1*(lower[tok]) in ("1";"t";"true");ok:1]]];

        if[not ok;if[at~"c";
          if[(count tok)=1;effective,:at;chars,:code[tok];ok:1]]];

        if[not ok;if[at~"s";effective,:at;syms,:enlist tok;symidx,:count[syms]-1;ok:1]];

        if[ok;j:count alt]];
      if[not ok;effective,:tc;syms,:enlist tok;symidx,:count[syms]-1]];

    if[not (effective[count effective]-1)~tc;recast+:1];
    i+:1];

  `effective`longs`floats`bools`chars`syms`symIdx`recast`total
    (string effective;longs;floats;bools;chars;distinct syms;symidx;recast;
      0.001f*floor (0.5f+1000f*(sum longs)+sum floats+sum bools+sum chars+sum symidx))}
