solve:{[tokens;codes]
  norm:{lower x};vals:();longs:();floats:();bools:();chars:();syms:();symidx:();effective:"";recast:0;i:0;
  while[i<count tokens;t:tokens i;decl:codes i;at:();done:0;
    at:((enlist "j");(enlist "f");(enlist "b");(enlist "c");(enlist "s")) where not ((enlist decl) in (enlist "j");(enlist decl) in (enlist "f");(enlist decl) in (enlist "b");(enlist decl) in (enlist "c");(enlist decl) in (enlist "s"));
    j:0;while[(j<count at)&not done;code:at j;ok:0;v:"";
      if[code~"j";v:{$[first[x]~"-";-1_x;x]} t;
        if[(count v)&all v in "0123456789";ok:1]];
      if[code~"f";v:{$[first[x]~"-";-1_x;x]} t;
        if[(count v)&all v in "0123456789.";ok:1]];
      if[code~"b";v:norm t;
        if[v in ("0";"1";"t";"f";"true";"false");ok:1]];
      if[code~"c";if[(count t)=1;ok:1]];
      if[code~"s";ok:1];
      if[ok;vals,:v;effective,:code;
        if[code~"j";longs,:("J"$v);done:1];
        if[code~"f";floats,:((0.001*floor (0.5|("F"$v)*1000)));done:1];
        if[code~"b";bools,:((v in ("1";"t";"true"))*1);done:1];
        if[code~"c";chars,:enlist first t;done:1];
        if[code~"s";
          if[not v in syms;syms,:enlist v];
          symidx,:first where syms~v;done:1];
        j+:1];
    if[not done;vals,:t;effective,:enlist "s";
      if[not t in syms;syms,:enlist t];symidx,:first where syms~t];
    if[not code~decl;recast+:1];i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
    (effective;longs;floats;bools;chars;syms;symidx;recast;
      0.001*floor 0.5+1000f*(sum longs)+sum floats+sum bools+sum chars+sum symidx)}
