solve:{[tokens;codes]
  norm:{[s] s where s in "0123456789."};
  j:{[t]
    a:abs "j"$t;
    (t matches "-?[0-9]+")&a<1000000000};
  f:{[t]
    a:abs "f"$t;
    (t matches "-?([0-9]+(\\.[0-9]*)?|\\.[0-9]+)")&a<1000000.0};
  b:{[t] t in "01tfTF";};
  c:{[t] 1=count t};
  codes2:("j";"f";"b";"c";"s");
  longs:();floats:();bools:();chars:();syms:();symidx:();eff:"";recast:0;total:0f;i:0;
  while[i<count tokens;
    t:norm tokens i;claimed:codes i;effc:"";val:0f;
    k:0;
    while[k<count codes2;
      c:codes2 k;
      ok:0;
      if[c~"j";ok:j t];
      if[c~"f";ok:f t];
      if[c~"b";ok:b t];
      if[c~"c";ok:c t];
      if[c~"s";ok:1];
      if[ok;effc:c;
        if[c~"j";val:"j"$t;longs,:val];
        if[c~"f";val:0.001*floor (1000f*(abs "f"$t))+0.5;floats,:val];
        if[c~"b";val:"j"$((lower t) in "1ttrue");bools,:val];
        if[c~"c";val:"j"$t;chars,:val];
        if[c~"s";
          if[not t in syms;syms,:enlist t];
          val:first where syms~t;symidx,:val];
        if[not c~claimed;recast+:1];
        k:count codes2];
      k+:1];
    total+:val;eff,:"j"$effc;i+:1];
  `effective`longs`floats`bools`chars`syms`symIdx`recast`total!
    (eff;longs;floats;bools;chars;syms;symidx;recast;total)}
